					t.Errorf("following declaration moved: %+v", e)
				}
			}
			masked := maskPostgresUnsupportedSyntax(src)
			if len(masked) != len(src) {
				t.Fatal("changed source width")
			}
			for i := range src {
				if (src[i] == '\n' || src[i] == '\r') && src[i] != masked[i] {
					t.Fatal("moved newline")
				}
			}
		})
	}
}

